    <div className="saved-grid">{answers.map((a,i)=><article className="card saved-card" key={a[0]}><div className="saved-card-head"><div className="ai-orb small"><Icon name="spark"/></div><Badge tone={i===0?'success':'info'}>{i===0?'Security':'Company knowledge'}</Badge><button><Icon name="more"/></button></div><h2>{a[0]}</h2><p>{a[1]}</p><button className="saved-source" onClick={openPreview}><Icon name="file"/><span>{a[2]}</span><Icon name="external"/></button><footer><span>Saved {a[3]}</span><div><button><Icon name="copy"/></button><button><Icon name="bookmark"/></button></div></footer></article>)}</div>
